const fs = require('node:fs');
const crypto = require('node:crypto');
const dir = 'products/services/contracts-finder-small-data-job';
const bytes = fs.readFileSync(`${dir}/official-feed.json`);
const hash = crypto.createHash('sha256').update(bytes).digest('hex');
if (hash !== '33d85ed3b5e0b38258cf283e4a3481dec45102ba444b62c0f83230a8b3e5b6e0') throw new Error('Feed hash differs from fetch receipt');
const source = JSON.parse(bytes);
if (!Array.isArray(source.releases)) throw new Error('Expected an OCDS releases array');
const terms = /\b(csv|spreadsheet|data (?:cleansing|cleaning|validation|migration|conversion|quality|entry)|catalogu[e]? data|file conversion)\b/i;
const rows = source.releases.filter(release => release.tender).map(release => {
  const tender = release.tender;
  const lots = Array.isArray(tender.lots) ? tender.lots : [];
  const text = [tender.title, tender.description, ...lots.flatMap(lot => [lot.title, lot.description])].filter(value => typeof value === 'string').join('\n');
  const match = terms.exec(text);
  return {id: release.id ?? null, ocid: release.ocid ?? null, title: tender.title ?? null, status: tender.status ?? null, deadline: tender.tenderPeriod?.endDate ?? null, matchedPhrase: match?.[0] ?? null, excerpt: match ? text.slice(Math.max(0, match.index - 100), match.index + 180) : null};
});
const candidates = rows.filter(row => row.matchedPhrase);
const output = `${dir}/feed-screen.json`;
fs.writeFileSync(output, JSON.stringify({sourceSha256: hash, releaseCount: source.releases.length, tenderCount: rows.length, candidates, limitation: 'Keyword screen of one saved feed page. Matches do not establish standalone scope, eligibility, acceptance criteria, a current deadline or an authorized submission route. Unmatched notices may still contain relevant work.'}, null, 2) + '\n');
const saved = JSON.parse(fs.readFileSync(output, 'utf8'));
console.log(JSON.stringify({output, releaseCount: saved.releaseCount, tenderCount: saved.tenderCount, candidateCount: saved.candidates.length}));
